class Disk {
	constructor(x, y, r) {
		this.x = x;
		this.y = y;
		this.r = r;
	}
}


class Dotty {
	constructor(a, s, shape) {
		this.shape = shape;
		this.baseHue = random(360);
		this.HZa = a; // HURWITZ ZETA 'a' param
		this.HZs = s; // HURWITZ ZETA 's' param
		this.plotsize = width;
		this.initial_k = 0;
		this.diskCount = 0; // number of disks placed

		this.k = this.initial_k; // index of the next disk to be placed
		this.diskArea = 1 / pow(this.HZa + this.k, this.HZs); // Initial HURWITZ ZETA FUNCTION
		this.diskRadius = sqrt(this.diskArea / PI); // Calc radius from area

		this.boxSide = 2.0; // math is performed in a 2x2 box then scaled to the screen

		// We're going to partition the box into cells to improve the
		// efficiency of testing for overlaps. This constant defines the
		// size of the grid. (20 rows x 20 cols = 400 cells)
		this.cellRowsCols = 20;
		this.diskData = new Array(this.cellRowsCols);
		for (let i = 0; i < this.cellRowsCols; i++) {
			this.diskData[i] = new Array(this.cellRowsCols);
			for (let j = 0; j < this.cellRowsCols; j++) {
				this.diskData[i][j] = [];
			}
		}

		this.bigDisks = []; // array of the biggest disks
		this.bigLimit = (this.boxSide / this.cellRowsCols) / 2; // maximum size to store in the bigDisk array

		// To avoid stalling the UI for long periods, we run the search for
		// a new disk site in batches.
		this.batchSize = 5000;

		this.coordToIndex = function(c) {
			return floor(c / this.boxSide * this.cellRowsCols);
		}
	}

	// The inner-loop routine for producing a new disk. Create
	// the new Disk object and assign the current radius, then
	// repeatedly try to find an xy location where you can put it,
	// for each trial checking for overlaps with the box boundaries
	// and all the previous disks. On success, return the Disk; after
	// 'batchSize' tries, give up and return false.
	newDisk() {
		let d = new Disk();
		d.r = this.diskRadius;
		if (d.r<3/width) return false; // too small
		let attempt = 1;
		let _wG_1 = 0; while ((attempt <= this.batchSize) && ++_wG_1 < 20000) {
			if (this.shape == 0) { //square
				d.x = random(d.r, max(this.boxSide, this.boxSide - d.r));
				d.y = random(d.r, max(this.boxSide, this.boxSide - d.r));
			} else {
				let theta = random(TAU);
				let r = sqrt(random()) - d.r; //uniform distribution on a disc
				d.x = r * cos(theta) + 1;
				d.y = r * sin(theta) + 1;
			}
			if (this.isInBounds(d) && this.isNotOverlapping(d)) {
				return d;
			}
			attempt++;
		}
		return false;
	}

	// The big disks go onto bigDisks; smaller disks are entered into
	// the appropriate cell of the geographic database.
	recordDisk(d) {
		if (d.r >= this.bigLimit) {
			this.bigDisks.push(d);
		} else {
			let cellX = this.coordToIndex(d.x);
			let cellY = this.coordToIndex(d.y);
			this.diskData[cellX][cellY].push(d);
		}
	}

	// Check a disk for overlap with the boundary of the outline
	// shape and return the result.
	isInBounds(d) {
		if (this.shape == 0) { //square
			return d.x - d.r >= 0 &&
				d.x + d.r <= this.boxSide &&
				d.y - d.r >= 0 &&
				d.y + d.r <= this.boxSide;
		} else { // circle
			return (dist(d.x, d.y, 1, 1) + d.r < this.boxSide / 2);
		}
	}

	// Given a disk, check for overlap with all the disks
	// already placed. This starts with a check against the
	// elements of bigDisks, then against the members of
	// all cells that could conceivably overlap. These are
	// the central cell and the eight neighboring cells.
	isNotOverlapping(disk) {
		for (const d of this.bigDisks) {
			if (this.disksOverlap(disk, d)) {
				return false; // intersects at least one big disk
			}
		}
		const cellX = this.coordToIndex(disk.x);
		const cellY = this.coordToIndex(disk.y);
		for (let xOffset = -1; xOffset <= 1; xOffset++) {
			let x = cellX + xOffset;
			if (x < 0 || x >= this.cellRowsCols) {
				continue;
			}
			for (let yOffset = -1; yOffset <= 1; yOffset++) {
				let y = cellY + yOffset;
				if (y < 0 || y >= this.cellRowsCols) {
					continue;
				}
				let cell = this.diskData[x][y];
				for (const d of cell) {
					if (this.disksOverlap(disk, d)) {
						return false;
					}
				}
			}
		}
		return true; // no overlaps with any of the tested disks
	}

	// Given two disks, return true if they overlap. avoids the sqrt function from distance calculations
	disksOverlap(d, e) {
		let deltaX = d.x - e.x;
		let deltaY = d.y - e.y;
		let s = d.r + e.r;
		return sq(deltaX) + sq(deltaY) < sq(s);
	}

	// Here, finally, we actually draw the disk to the screen
	// Includes so nifty grain image rendering as an OVERLAY if the disk is large enough to be worth it
	drawDisk(disk) {
		let sx = map(disk.x, 0, 2, 0.1 * width, 0.9 * width);  //scaling for whitespace boundary
		let sy = map(disk.y, 0, 2, 0.1 * width, 0.9 * width);  //scaling for whitespace boundary
		let sr = map(disk.r, 0, 2, 0, 0.8 * width); //scaling for whitespace boundary

		fill(0, 0, 0, 20);  
		circle(sx + width / 1000, sy + width / 1000, sr * 2);  // shadow offset is resolution independant

		for (let i = floor(sr); i > 0; i--) { //loop to fake a highlight by drawing successively lighter circles
			let r = map(i, floor(sr), 0, sr, sr / 10);
			let s = map(i, floor(sr), 0, 100, 0);
			let b = map(i, floor(sr), 0, 30, 100);
			let offset = map(i, floor(sr), 0, 0, -sr / 1.9);  

			fill(color((this.baseHue + pow(this.k + 1, 0.75)) % 360, s, b));  //this is the power function for the hue
			circle(sx + offset, sy + offset, r * 2);
		}

    //create and apply grain overlay if disk is large enough
		if (sr > 4) {
			let graincopy = createImage(floor(2 * sr + 1), floor(2 * sr + 1));
			let gcw = graincopy.width;
			let gch = graincopy.height;

			graincopy.loadPixels();
			for (let y = 0; y < gch; y++) {
				for (let x = 0; x < gcw; x++) {
					let i = (x + y * gcw) << 2;
					let gA = 25;
					graincopy.pixels[i] = random(127 - gA, 127 + gA);
					graincopy.pixels[i + 1] = random(127 - gA, 127 + gA);
					graincopy.pixels[i + 2] = random(127 - gA, 127 + gA);

					if (sq(x - gcw / 2) + sq(y - gch / 2) < sr * sr) {
						graincopy.pixels[i + 3] = 255;
					} else {
						graincopy.pixels[i + 3] = 0;
					}
				}
			}
			graincopy.updatePixels();

			push();
			blendMode(OVERLAY);
			image(graincopy, sx - sr, sy - sr);
			pop();
		}
	}

	// the main function to call
	doOneDisk() {
		const d = this.newDisk();

		if (!d) { // If d == false, we stalled trying to get a disk locations
			return false;
		}

		// If we've gotten this far, we have a disk and the disk has a home.
		// So we record it in the database and update the variables that keep 
		// track of the count of disks.

		this.recordDisk(d);
		this.diskCount++;

		// Draw the disk
		this.drawDisk(d);

		// increment the index k, then calculate the area and radius
		// of the next disk to be placed.
		this.k++;

		this.diskArea = 1 / pow(this.HZa + this.k, this.HZs); // HURWITZ ZETA FUNCTION
		this.diskRadius = sqrt(this.diskArea / PI);

		return true;
	}

}

