let theDots, stallcount, a;
let maxStalls = 30; //number of stalls before "finishing"
let paused, endpause;
let pauseMillis = 5000; //delay before restarting
let chop;
let process = true;
let seedOverride;  // leave blank for random, set to regenerate a particular image

const s_array = [
	[0, 1.287, 1.200, 1.171, 1.155, 1.137], // selected to maximize the percentage goverage with reasonable speed in a square canvas 
	[0, 1.4023, 1.27, 1.231, 1.209, 1.205] // selected to maximize the percentage goverage with reasonable speed in a round canvas 
]

function preload() {
	chop = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/RMAchop.png');
}

function setup() {
	//set up the chop image once
	if (process) {
		chop.filter(INVERT);
		chop.filter(BLUR, 3);
		process = false;
	}

	seed = seedOverride??floor(random(Number.MAX_SAFE_INTEGER));
	randomSeed(seed);

	//set up the image
	let h = max(windowWidth, windowHeight)
	createCanvas(h * 0.9, h);
	smooth();
	background(255);
	a = floor((sqrt(random())) * 4 + 1); // HURWITZ ZETA FUNCTION 'a' parameter
	let t = floor(random(2)); // 0=square, round=1 canvas shape
	let s = s_array[t][a]; //HURWITZ ZETA FUNCTION 's' parameter from lookup array
	theDots = new Dotty(a, s, t);
	noStroke();
	stallcount = 0; //reset the stall counter

	//draw the frame
	drawFrame();

	colorMode(HSB, 360, 100, 100, 100);
	paused = false;
}

function draw() {
	if (paused && millis() > endpause) setup(); //pause is done. Restart

	if (paused) return;

	//not paused generate 10 per frame... seems like a good number
	for (let i = 0; i < 10; i++) {
		if (!theDots.doOneDisk()) { //draw some dots
			stallcount++;
		}
	}

	if (theDots.diskCount < 2) setup(); // just restart, it was a bad first placement

	//animate the "progress" bar
	push();
	fill(255);
	translate(0, height);
	scale(1, -1); // too lazy to recode the math to but the bar at the bottom of the screen....
	rectMode(CORNER);
	rect(0, 0, width, width * 0.03);
	fill(0, 0, 50);
	rect(0, 0, 1 + width * (maxStalls - stallcount) / (maxStalls + 1), width * 0.02); //pulse bar
	rect(width * (maxStalls - stallcount) / (maxStalls + 1), 0, (100 - (frameCount % 100)) * width / (maxStalls + 1) / 100, width * 0.02); //pulse bar
  pop();


	// if stalled, draw the chop and pause to we can grab an image save with the LMB
	if (stallcount >= maxStalls) {
		paused = true;

		//blank the progress bar
		push();
		fill(255);
		translate(0, height);
		scale(1, -1); // too lazy to recode the math to but the bar at the bottom of the screen....
		rectMode(CORNER);
		rect(0, 0, width, width * 0.03);
		pop();

		//outline the image
		noFill();
		stroke(0);
		strokeWeight(2);
		rect(0, 0, width, height);
		endpause = millis() + pauseMillis;

		// output data;
		noStroke();
		fill(0,0,75);
		textSize(height / 100);
		textAlign(LEFT, BOTTOM);
		let oText = "Max Stalls=" + maxStalls + ", Seed:" + seed + ", Disks Generated: " + theDots.diskCount;
		text(oText, 0.06 * width, height - 0.06 * width);

		tint(0, 100, 65, 70); // Red tint for the chop
		image(chop, 0.85 * width, height - 0.15 * width, 0.05 * width, 0.05 * width);
		noTint();
	}
}

function drawFrame() {
	//draw picture frame
	colorMode(RGB);
	let go = 0.05;
	let gi = 0.058;
	fill(150); //top
	beginShape();
	vertex(width * go, width * go);
	vertex(width * (1 - go), width * go);
	vertex(width * (1 - gi), width * gi);
	vertex(width * gi, width * gi);
	endShape(CLOSE);
	fill(220); //right
	beginShape();
	vertex(width * (1 - go), width * go);
	vertex(width * (1 - go), height - width * go)
	vertex(width * (1 - gi), height - width * gi);
	vertex(width * (1 - gi), width * gi);
	endShape(CLOSE);
	fill(240); //bottom
	beginShape();
	vertex(width * go, height - width * go);
	vertex(width * (1 - go), height - width * go);
	vertex(width * (1 - gi), height - width * gi);
	vertex(width * gi, height - width * gi);
	endShape(CLOSE);
	fill(170); //left
	beginShape();
	vertex(width * go, width * go);
	vertex(width * go, height - width * go);
	vertex(width * gi, height - width * gi);
	vertex(width * gi, width * gi);
	endShape(CLOSE);
}

